# Собирает index.html из index.html.tpl: вставляет субтитры по пословным таймингам озвучки (ElevenLabs Scribe).
# Запуск: python3 gen_captions.py index.html.tpl index.html
import sys, html
OFF = 0.2
W = [("Подписка",0,0.56),("на",0.64,0.72),("одну",0.76,0.88),("нейросеть,",0.96,1.84),("ещё",2.16,2.4),("одна",2.44,2.56),("на",2.64,2.72),("другую,",2.76,3.36),("третья",3.6,3.92),("на",3.96,4.0),("третью?",4.08,4.72),("Хватит.",4.96,5.84),("Ketner",6.24,6.56),("AI —",6.64,7.28),("все",7.36,7.6),("сильные",7.68,7.92),("модели",8.0,8.24),("в",8.32,8.347),("одной",8.373,8.56),("подписке.",8.64,9.32),("GPT,",9.6,10.32),("Claude,",10.56,11.08),("Gemini,",11.28,11.88),("Grok",12.08,12.48),("и",12.56,12.64),("DeepSeek —",12.72,13.387),("в",13.413,13.44),("одном",13.48,13.68),("чате.",13.76,14.36),("Режим",14.56,14.88),("Auto",15.04,15.36),("сам",15.44,15.6),("выберет",15.68,15.92),("модель",16.0,16.24),("под",16.32,16.4),("вашу",16.48,16.68),("задачу.",16.72,17.44),("Пишите",17.68,18.08),("код",18.16,18.24),("с",18.32,18.36),("агентом,",18.4,18.96),("создавайте",19.12,19.68),("картинки,",19.76,20.36),("подключайте",20.56,21.12),("API",21.2,21.52),("в",21.547,21.573),("формате",21.6,22.0),("OpenAI.",22.08,22.84),("Тарифы —",23.12,23.813),("от",23.867,23.92),("нуля",24.0,24.16),("до",24.2,24.24),("сорока",24.32,24.56),("девяти",24.64,24.88),("долларов",24.96,25.28),("в",25.32,25.36),("месяц.",25.44,26.0),("Начните",26.16,26.56),("бесплатно",26.64,27.12),("на",27.2,27.36),("ketner.org",27.4,28.56)]
# phrase groups (word index ranges), chosen by meaning, ≤ ~20 chars per line
G = [(0,4),(4,8),(8,11),(11,12),(12,14),(14,17),(17,20),(20,23),(23,26),(26,29),(29,31),(31,34),(34,37),(37,41),(41,43),(43,45),(45,48),(48,51),(51,54),(54,57),(57,59),(59,61)]
assert G[-1][1]==len(W)
html_out=[]; js=[]
for gi,(a,b) in enumerate(G):
    words=W[a:b]
    spans=" ".join(f'<span class="wd" id="w{gi}-{k}">{html.escape(t)}</span>' for k,(t,_,_) in enumerate(words))
    html_out.append(f'        <div class="cap" id="cap{gi}"><p>{spans}</p></div>')
    start=words[0][1]+OFF-0.05
    nxt = W[G[gi+1][0]][1]+OFF-0.05 if gi+1<len(G) else 30.3
    end=min(nxt, words[-1][2]+OFF+0.5)
    js.append(f'      tl.fromTo("#cap{gi}", {{ opacity: 0, y: 14 }}, {{ opacity: 1, y: 0, duration: 0.12, ease: "none" }}, {start:.3f});')
    js.append(f'      tl.to("#cap{gi}", {{ opacity: 0, duration: 0.08, ease: "none" }}, {end-0.08:.3f});')
    for k,(t,ws,we) in enumerate(words):
        js.append(f'      tl.fromTo("#w{gi}-{k}", {{ color: "#ffffff" }}, {{ color: "#9eefd0", duration: 0.06, ease: "none" }}, {ws+OFF:.3f});')
src=open(sys.argv[1]).read()
src=src.replace("<!--CAPTIONS-->","\n".join(html_out)).replace("/*CAPTIONS*/","\n".join(js))
open(sys.argv[2],"w").write(src)
print(len(G),"groups")
